// Always returns exactly one item so the IF node after it can decide.
const first = $input.first();
const res = (first && first.json && first.json.esearchresult) || {};
const ids = Array.isArray(res.idlist) ? res.idlist : [];
return [{ json: { ids: ids.join(','), count: ids.length } }];

const first = $input.first();
const root = (first && first.json) || {};
const set = root.PubmedArticleSet;
let articles = (set && set.PubmedArticle) || [];
if (!Array.isArray(articles)) articles = [articles];

function textOf(node) {
  if (node === undefined || node === null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(textOf).join(' ');
  if (typeof node === 'object') return textOf(node._ || node['#text'] || '');
  return String(node);
}
function pad(n) { return String(n).padStart(2, '0'); }

const out = [];
for (const a of articles) {
  const medline = a.MedlineCitation || {};
  const article = medline.Article || {};
  const pmid = textOf(medline.PMID).trim();
  if (!pmid) continue;
  const title = textOf(article.ArticleTitle).trim() || '(no title)';
  const abstract = textOf(article.Abstract && article.Abstract.AbstractText).trim();
  const journal = article.Journal && article.Journal.Title ? textOf(article.Journal.Title).trim() : '';

  let date = '';
  const ad = Array.isArray(article.ArticleDate) ? article.ArticleDate[0] : article.ArticleDate;
  if (ad && ad.Year) {
    date = [textOf(ad.Year), pad(textOf(ad.Month) || '1'), pad(textOf(ad.Day) || '1')].join('-');
  } else {
    const pd = article.Journal && article.Journal.JournalIssue && article.Journal.JournalIssue.PubDate;
    date = pd ? (textOf(pd.Year) || textOf(pd.MedlineDate).slice(0, 4)) : '';
  }

  out.push({
    json: {
      source: 'PubMed',
      sourceType: 'literature',
      title,
      journal,
      date,
      link: 'https://pubmed.ncbi.nlm.nih.gov/' + pmid + '/',
      text: title + '. ' + abstract
    }
  });
}
return out;

const first = $input.first();
const body = (first && first.json) || {};
const hits = (body.hits && body.hits.hits) || [];

return hits.map(h => {
  const md = h.metadata || {};
  const desc = String(md.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const creators = (md.creators || []).map(c => c.name).slice(0, 3).join(', ');
  const title = String(md.title || '(no title)').trim();
  return {
    json: {
      source: 'Zenodo',
      sourceType: 'literature',
      title,
      journal: creators,
      date: md.publication_date || '',
      link: (h.links && (h.links.self_html || h.links.html)) || '',
      text: title + '. ' + desc
    }
  };
});

const first = $input.first();
const data = (first && first.json) || {};
const results = (data.response && data.response.results) || [];

function cleanHtml(value) {
  return String(value || '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

return results
  .filter(a => a.type === 'article')
  .map(a => {
    const f = a.fields || {};
    const title = cleanHtml(f.headline || a.webTitle || '(no title)');
    const body = cleanHtml(f.body || f.trailText || '');
    return {
      json: {
        source: 'The Guardian',
        sourceType: 'news',
        title,
        journal: 'The Guardian',
        date: String(a.webPublicationDate || '').slice(0, 10),
        link: a.webUrl || '',
        text: (title + '. ' + body).trim(),
        section: a.sectionName || ''
      }
    };
  });

// Fallback list, used only if vocab.json could not be loaded from GitHub.
const FALLBACK = {
  strongWords: ['delve', 'delves', 'delving', 'tapestry', 'intricate', 'intricacies', 'meticulous', 'meticulously', 'underscore', 'underscores', 'underscoring', 'showcasing', 'commendable', 'multifaceted', 'myriad', 'plethora', 'testament'],
  weakWords: ['pivotal', 'crucial', 'robust', 'comprehensive', 'notably', 'furthermore', 'moreover', 'leverage', 'leveraging', 'foster', 'fostering', 'paradigm', 'holistic', 'landscape'],
  explicitPhrases: ['as an ai language model', 'as a large language model', 'as an ai assistant', 'regenerate response', 'as of my last knowledge update'],
  weights: { strong: 2, weak: 0.5 },
  thresholds: { minWords: 80, minStrongHits: 2, elevatedMinStrongHits: 3, moderate: 1.5, elevated: 3.0 }
};

let vocab = FALLBACK;
try {
  const v = $('Load vocab.json').first().json;
  if (v && Array.isArray(v.strongWords) && v.thresholds && v.weights) vocab = v;
} catch (e) { /* keep fallback */ }

function scoreText(rawText, vocab) {
  const text = String(rawText || '');
  const lower = text.toLowerCase();
  const wordCount = text.trim() ? text.trim().split(/\s+/).length : 0;
  const t = vocab.thresholds;
  const matched = {};
  let strongHits = 0;
  let weakHits = 0;

  function countWords(list, isStrong) {
    for (const w of list) {
      const re = new RegExp('(?<![\\w-])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?![\\w-])', 'gi');
      const n = (text.match(re) || []).length;
      if (n > 0) {
        matched[w] = (matched[w] || 0) + n;
        if (isStrong) strongHits += n; else weakHits += n;
      }
    }
  }
  countWords(vocab.strongWords, true);
  countWords(vocab.weakWords, false);

  let explicitHit = null;
  for (const p of vocab.explicitPhrases) {
    if (lower.includes(p)) { explicitHit = p; break; }
  }

  const weighted = wordCount > 0
    ? ((strongHits * vocab.weights.strong + weakHits * vocab.weights.weak) / wordCount) * 100
    : 0;

  let level = 'none';
  const tooShort = wordCount < t.minWords;
  const strongOk = strongHits >= (t.minStrongHits || 1);
  if (explicitHit) level = 'explicit';
  else if (!tooShort && strongHits >= (t.elevatedMinStrongHits || t.minStrongHits || 1) && weighted >= t.elevated) level = 'elevated';
  else if (!tooShort && strongOk && weighted >= t.moderate) level = 'moderate';

  const top = Object.entries(matched).sort((a, b) => b[1] - a[1]).slice(0, 8)
    .map(([w, n]) => (n > 1 ? w + ' x' + n : w));

  return {
    words: wordCount,
    tooShort,
    strongHits,
    weakHits,
    weighted: Number(weighted.toFixed(2)),
    level,
    explicitHit,
    matched: top
  };
}


const seen = new Set();
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.link || !j.text) continue;
  if (seen.has(j.link)) continue;
  seen.add(j.link);
  const s = scoreText(j.text, vocab);
  out.push({
    json: {
      ...j,
      words: s.words,
      tooShort: s.tooShort,
      vocabLevel: s.level,
      vocabWeighted: s.weighted,
      vocabStrong: s.strongHits,
      vocabWeak: s.weakHits,
      matched: s.matched,
      explicitHit: s.explicitHit
    }
  });
}
return out;

// Turn the vocabulary score into a tier. No external detector is used.
//   strong = leftover chatbot phrase, or elevated vocabulary drift
//   weak   = moderate vocabulary drift
//   none   = everything else
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (!j.link) continue;

  let signal = 'none';
  if (j.vocabLevel === 'explicit' || j.vocabLevel === 'elevated') signal = 'strong';
  else if (j.vocabLevel === 'moderate') signal = 'weak';

  const reasons = [];
  if (j.explicitHit) reasons.push('Leftover chatbot phrase: "' + j.explicitHit + '"');
  if (j.vocabLevel === 'moderate' || j.vocabLevel === 'elevated') {
    reasons.push('Vocabulary drift (' + j.vocabLevel + '): ' + j.vocabStrong + ' strong word(s), weighted density ' + j.vocabWeighted + ' per 100 words');
  }

  out.push({
    json: {
      source: j.source,
      sourceType: j.sourceType,
      title: j.title,
      journal: j.journal,
      date: j.date,
      link: j.link,
      words: j.words,
      tooShort: j.tooShort,
      vocabLevel: j.vocabLevel,
      vocabWeighted: j.vocabWeighted,
      matched: j.matched,
      explicitHit: j.explicitHit,
      detectorScore: null,
      detectorProvider: null,
      signal,
      reasons
    }
  });
}
return out;

// Merge today's results into the history file, update run statistics, and build the email.
const scored = $input.all().map(i => i.json || {}).filter(j => j.link);

const cfg = $('Config').first().json || {};
const retentionDays = Number(cfg.retentionDays) || 90;
const today = new Date().toISOString().slice(0, 10);
const cutoff = new Date(Date.now() - retentionDays * 86400000).toISOString().slice(0, 10);

let hist = {};
try { hist = $('Load history').first().json || {}; } catch (e) { hist = {}; }
const oldItems = Array.isArray(hist.items) ? hist.items : [];
const oldRuns = Array.isArray(hist.runs) ? hist.runs : [];

// Only flagged articles are published. Unflagged articles are counted, not listed.
const flaggedNow = scored.filter(j => j.signal !== 'none');

const byLink = new Map();
oldItems.forEach(i => { if (i && i.link) byLink.set(i.link, i); });
flaggedNow.forEach(j => {
  if (!byLink.has(j.link)) {
    const { tooShort, ...rest } = j;
    byLink.set(j.link, { ...rest, firstSeen: today });
  }
});

const rank = { strong: 3, weak: 2, none: 1 };
const items = Array.from(byLink.values())
  .filter(i => (i.firstSeen || today) >= cutoff)
  .sort((a, b) =>
    (rank[b.signal] - rank[a.signal]) ||
    ((b.vocabWeighted ?? 0) - (a.vocabWeighted ?? 0)) ||
    String(b.firstSeen).localeCompare(String(a.firstSeen))
  );

const bySource = {};
scored.forEach(j => { bySource[j.source] = (bySource[j.source] || 0) + 1; });

const run = {
  date: today,
  scanned: scored.length,
  bySource,
  tooShort: scored.filter(j => j.tooShort).length,
  strong: items.filter(i => i.firstSeen === today && i.signal === 'strong').length,
  weak: items.filter(i => i.firstSeen === today && i.signal === 'weak').length
};

const runs = oldRuns.filter(r => r && r.date !== today).concat([run]).slice(-retentionDays);

const file = { schema: 2, generatedAt: new Date().toISOString(), lastRun: run, runs, items };
const fileContent = JSON.stringify(file, null, 1);

// ---------- Email ----------
function esc(s) {
  return String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
}
const todays = items.filter(i => i.firstSeen === today && i.signal !== 'none');

// For tuning the thresholds: the highest vocabulary scores among articles that were NOT flagged.
const nearMiss = scored
  .filter(j => j.signal === 'none' && !j.tooShort && j.vocabWeighted > 0)
  .sort((a, b) => b.vocabWeighted - a.vocabWeighted)
  .slice(0, 5);

function row(i) {
  const tier = i.signal === 'strong' ? 'STRONG' : i.signal === 'weak' ? 'WEAK' : 'NOT FLAGGED';
  const col = i.signal === 'strong' ? '#B3261E' : i.signal === 'weak' ? '#9A6A0C' : '#666';
  return '<tr>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;color:' + col + ';font-weight:600;white-space:nowrap">' + tier + '</td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd"><a href="' + esc(i.link) + '">' + esc(i.title) + '</a><br><span style="color:#666;font-size:12px">' + esc(i.source) + '</span></td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;text-align:right">' + esc(i.vocabWeighted) + '</td>' +
    '<td style="padding:6px 8px;border-bottom:1px solid #ddd;font-size:12px">' + esc((i.explicitHit ? '"' + i.explicitHit + '" ' : '') + (i.matched || []).join(', ')) + '</td>' +
    '</tr>';
}
function table(list) {
  return '<table style="border-collapse:collapse;width:100%;font-size:14px"><tr style="text-align:left;color:#555">' +
    '<th style="padding:6px 8px">Signal</th><th style="padding:6px 8px">Article</th>' +
    '<th style="padding:6px 8px;text-align:right">Vocab /100w</th><th style="padding:6px 8px">Matched</th></tr>' +
    list.map(row).join('') + '</table>';
}

let html = '<div style="font-family:Arial,sans-serif;max-width:720px;color:#1B2430">' +
  '<h2 style="margin:0 0 8px">Redline Watch - ' + esc(today) + '</h2>' +
  '<p style="margin:0 0 12px">' + run.scanned + ' records scanned (' + (Object.keys(bySource).map(k => esc(k) + ' ' + bySource[k]).join(', ') || 'none') + '). ' +
  run.tooShort + ' were too short to score. ' + run.strong + ' strong and ' + run.weak + ' weak signals today.</p>';

if (run.scanned === 0) {
  html += '<p style="color:#B3261E"><b>No records were scanned.</b> A source or the search query is probably failing. Check the n8n execution log.</p>';
}
html += todays.length ? '<h3>Flagged today</h3>' + table(todays) : '<p>No flagged articles today.</p>';
if (nearMiss.length) {
  html += '<h3>Highest vocabulary scores that were not flagged</h3>' +
    '<p style="color:#666;font-size:12px;margin:0 0 6px">Shown only in this email, to help you tune the thresholds in vocab.json. They are not published.</p>' + table(nearMiss);
}

html += '<p style="margin-top:18px"><a href="https://ramiabouaziz.github.io/AI-Articles/redline-watch.html">Open the dashboard</a></p>' +
  '<p style="color:#666;font-size:12px">Signals come from vocabulary patterns and leftover chatbot phrases only; no AI detector is used. This is weak, population-level evidence. Short, formulaic or non-native English text can trigger false positives, and a clean result does not rule out AI assistance. These are leads for a human reviewer, not proof of authorship.</p></div>';

const subject = 'Redline Watch - ' + (run.strong + run.weak) + ' flagged of ' + run.scanned + ' scanned (' + today + ')';

return [{ json: { fileContent, subject, html, flaggedToday: todays.length, scanned: run.scanned } }];
